<?php require_once __DIR__.'/../includes/functions.php';require_role('admin');$pageTitle='Reports';$base='../';require __DIR__.'/../includes/header.php';$sets=['Students'=>'SELECT c.name,COUNT(s.id) total FROM classes c LEFT JOIN students s ON s.class_id=c.id GROUP BY c.id','Fees'=>'SELECT status,COUNT(*) records,SUM(total_amount) total,SUM(paid_amount) paid FROM fees GROUP BY status','Attendance'=>'SELECT attendance_date,SUM(status="Present") present,SUM(status="Absent") absent,SUM(status="Late") late FROM attendance GROUP BY attendance_date ORDER BY attendance_date DESC LIMIT 30'];?><div class="layout"><?php require __DIR__.'/../includes/sidebar.php';?><section class="content"><h1>Reports</h1><?php foreach($sets as $n=>$q):$rs=$pdo->query($q)->fetchAll();?><div class="card" style="margin-bottom:18px"><h2><?=e($n)?></h2><div class="table-wrap"><table class="table"><?php if($rs):?><tr><?php foreach(array_keys($rs[0]) as $h):?><th><?=e($h)?></th><?php endforeach;?></tr><?php foreach($rs as $r):?><tr><?php foreach($r as $v):?><td><?=e((string)$v)?></td><?php endforeach;?></tr><?php endforeach;?><?php endif;?></table></div></div><?php endforeach;?></section></div><?php require __DIR__.'/../includes/footer.php';?>